$ErrorActionPreference='Stop'
if($env:COMPUTERNAME -ne 'DESKTOP-O1LP5DG' -or (Get-CimInstance Win32_ComputerSystemProduct).UUID -ne 'C6440689-D11C-4C63-A463-F3722B7DDB69'){throw 'Wrong builder'}
$bytes=[Convert]::FromBase64String('')
$sha=[Security.Cryptography.SHA256]::Create()
if([BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','').ToLowerInvariant() -ne '924fd290282e50ae89cfd7d357a14bee73a87fce4da7c05bba50ba884178957d'){throw 'Source pin mismatch'}
$tokens=$null;$errors=$null
$ast=[Management.Automation.Language.Parser]::ParseInput([Text.Encoding]::UTF8.GetString($bytes),[ref]$tokens,[ref]$errors)
if($errors.Count){$errors|ConvertTo-Json;throw 'PowerShell parse failed'}
$fn=$ast.Find({param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -eq 'Invoke-NativeToLog'},$true)
if($null -eq $fn){throw 'Expected native capture function absent'}
Invoke-Expression $fn.Extent.Text
$log=Join-Path $env:TEMP ('exact-native-stderr-'+[Guid]::NewGuid().ToString('N')+'.txt')
try {
$code=Invoke-NativeToLog 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' @('-NoProfile','-NonInteractive','-Command',"[Console]::Error.WriteLine('EXACT_NATIVE_STDERR_FIXTURE'); exit 7") $log
if($code -ne 7 -or [IO.File]::ReadAllText($log) -notmatch 'EXACT_NATIVE_STDERR_FIXTURE'){throw 'Native stderr/exit preservation failed'}
@{UTC=[DateTime]::UtcNow.ToString('o');SourceSHA256='924fd290282e50ae89cfd7d357a14bee73a87fce4da7c05bba50ba884178957d';PowerShellSyntaxErrors=$errors.Count;NativeFailureExit=$code;StderrPreserved=$true;ErrorPreferenceRestored=($ErrorActionPreference -eq 'Stop')}|ConvertTo-Json
}finally{Remove-Item -LiteralPath $log -Force -ErrorAction SilentlyContinue}
